import json, numpy as np
from scipy.spatial.transform import Rotation as R
S=json.load(open('/app/output/spec.json'))
def tcp(meta):
 p=np.array(meta['proprio']['now']);t=np.eye(4);t[:3,3]=p[16:19];t[:3,:3]=R.from_quat(p[[20,21,22,19]]).as_matrix();return t
M=np.linalg.inv(tcp(json.load(open('/app/output/initial/meta.json'))))@np.array(S['cameras']['wrist']['cam2world_gl'])
def point(label,c,u,v):
 d=np.load(f'/app/output/{label}/depth_{c}.npy')[-1];z=float(d[v,u]);f=S['cameras'][c]['intrinsic_cv'][0][0]
 T=tcp(json.load(open(f'/app/output/{label}/meta.json')))@M if c=='wrist' else np.array(S['cameras'][c]['cam2world_gl'])
 return (T@np.array([(u-160)*z/f,-(v-160)*z/f,-z,1]))[:3]
if __name__=='__main__':
 for label in ['apple_approach','close_deep']:
  for uv in [(150,60),(150,100),(150,140),(160,165),(130,170),(190,170)]:print(label,uv,point(label,'wrist',*uv))
